// Class 12 English Core - Flamingo Poetry Chapter 11: A Thing of Beauty
// Fully standardized to English Core Blueprint & AGENTS.md guidelines

export const c12EngF11HtmlOverview = "\n<div style=\"padding: 18px; color: #F8FAFC; text-align: justify; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.85; font-size: 15px;\">\n  <!-- Chapter Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(0, 230, 118, 0.18), rgba(15, 23, 42, 0.95)); border: 1.5px solid #00E676; border-radius: 14px; padding: 22px; margin-bottom: 24px; box-shadow: 0 8px 24px rgba(0,0,0,0.35);\">\n    <div style=\"display: flex; align-items: center; gap: 12px; margin-bottom: 10px;\">\n      <span style=\"background: #00E676; color: #0F172A; font-weight: 800; font-size: 12px; padding: 4px 10px; border-radius: 6px; text-transform: uppercase; letter-spacing: 1px;\">Poem 11 • Flamingo Poetry</span>\n      <span style=\"color: #94A3B8; font-size: 13px; font-weight: 600;\">Core Literature • Class 12 English</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 26px; font-weight: 800; margin: 0 0 8px 0; letter-spacing: -0.5px;\">A Thing of Beauty</h1>\n    <p style=\"color: #00E676; font-size: 15px; font-weight: 600; margin: 0 0 12px 0;\">By John Keats (1795–1821) • An Excerpt from 'Endymion: A Poetic Romance' (1818)</p>\n    <p style=\"color: #CBD5E1; font-size: 14px; line-height: 1.6; margin: 0;\">An immortal Romantic ode affirming the eternal, transcendental power of artistic and natural beauty to dispel human suffering, melancholy, and moral gloom, serving as an endless fountain of celestial nectar.</p>\n  </div>\n\n  <!-- Poet Background & Context -->\n  <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #00E676; border-radius: 0 12px 12px 0; padding: 18px 20px; margin-bottom: 24px;\">\n    <h3 style=\"color: #00E676; margin: 0 0 10px 0; font-size: 18px; font-weight: 700;\">1. About the Poet & Classical Inspiration</h3>\n    <p style=\"margin: 0 0 10px 0;\">John Keats was one of the foremost luminaries of the English Romantic movement, alongside Shelley and Byron. Trained initially as an apothecary-surgeon, Keats devoted his brief, tragic life (dying of tuberculosis at age twenty-five) to capturing the transcendent truth of beauty, famously declaring in <i style=\"color: #00E676;\">Ode on a Grecian Urn</i>: <i style=\"color: #FFFFFF;\">\"Beauty is truth, truth beauty.\"</i></p>\n    <p style=\"margin: 0;\"><b style=\"color: #00E676;\">Mythological Genesis:</b> This poem is the opening passage of Keats's epic narrative poem <i style=\"color: #00E676;\">Endymion</i>, inspired by classical Greek mythology. Endymion, a breathtakingly handsome young shepherd-prince living on Mount Latmos, experiences visions of Cynthia, the virgin Moon Goddess, and embarks on an arduous quest through forest sanctuaries and undersea caverns to attain divine communion with her immortal grace.</p>\n  </div>\n\n  <!-- Stanza-by-Stanza Deep Analysis -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 12px; padding: 20px; margin-bottom: 24px;\">\n    <h3 style=\"color: #00E676; margin: 0 0 16px 0; font-size: 18px; font-weight: 700;\">2. Stanza-by-Stanza Critical Exploration</h3>\n    \n    <div style=\"margin-bottom: 16px; padding-bottom: 14px; border-bottom: 1px dashed rgba(255,255,255,0.1);\">\n      <h4 style=\"color: #F1F5F9; font-size: 15px; margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">Stanza 1: Eternal Nature of Beauty & The Peaceful Bower</b></h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 14px;\">Keats lays down his foundational philosophical axiom: <i style=\"color: #FFFFFF;\">\"A thing of beauty is a joy for ever.\"</i> Unlike physical objects of sensory gratification that degrade or fade into oblivion over time, authentic beauty possesses an ever-increasing loveliness that <i style=\"color: #FFFFFF;\">\"will never pass into nothingness.\"</i> It leaves an indelible imprint upon human consciousness, constructing a tranquil, shady sanctuary (<i style=\"color: #FFFFFF;\">\"a bower quiet for us\"</i>) that bestows sound sleep, restorative sweet dreams, somatic health, and serene breathing.</p>\n    </div>\n\n    <div style=\"margin-bottom: 16px; padding-bottom: 14px; border-bottom: 1px dashed rgba(255,255,255,0.1);\">\n      <h4 style=\"color: #F1F5F9; font-size: 15px; margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">Stanza 2: The Flowery Band & Counteracting Life's Gloom</b></h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 14px;\">Human existence is plagued by sorrow, spiritual malaise, and moral depravity: the <i style=\"color: #FFFFFF;\">\"inhuman dearth of noble natures\"</i>, pervasive despondence, gloomy days, and the <i style=\"color: #FFFFFF;\">\"unhealthy and o'er-darkened ways\"</i> men navigate in selfish pursuit of worldly success. Yet, despite this existential grief, human beings wake every morning (<i style=\"color: #FFFFFF;\">\"on every morrow\"</i>) weaving a metaphorical <i style=\"color: #FFFFFF;\">\"flowery band to bind us to the earth.\"</i> Beauty acts as an essential lifeline, anchoring man to terrestrial life.</p>\n    </div>\n\n    <div style=\"margin-bottom: 16px; padding-bottom: 14px; border-bottom: 1px dashed rgba(255,255,255,0.1);\">\n      <h4 style=\"color: #F1F5F9; font-size: 15px; margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">Stanza 3: The Catalogue of Natural Wonders (Boon & Solace)</b></h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 14px;\">Whenever darkness overwhelms the human spirit, <i style=\"color: #FFFFFF;\">\"some shape of beauty moves away the pall from our dark spirits.\"</i> Keats presents a lush sensory panorama of these healing agents: the golden sun, the silver moon, venerable old and tender young trees creating a hospitable shady canopy (<i style=\"color: #FFFFFF;\">\"a shady boon\"</i>) for innocent sheep. He evokes bright daffodils thriving in lush greenery, crystal clear streams (<i style=\"color: #FFFFFF;\">\"clear rills\"</i>) carving cool undergrowth shelters against scorching midsummer heat, and woodland clearings (<i style=\"color: #FFFFFF;\">\"mid forest brake\"</i>) perfumed by wild, blooming musk-roses.</p>\n    </div>\n\n    <div>\n      <h4 style=\"color: #F1F5F9; font-size: 15px; margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">Stanza 4: The Grandeur of Dooms & The Immortal Fountain</b></h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 14px;\">Keats expands his concept of beauty beyond pastoral nature to the sublime realm of human art, mythology, and heroic sacrifice: <i style=\"color: #FFFFFF;\">\"the grandeur of the dooms we have imagined for the mighty dead.\"</i> The magnificent, tragic destinies and valor of great ancestors, along with all immortal epics, legends, and ballads ever read or heard, stir deep aesthetic reverie. The poem concludes with an exalted cosmic metaphor: all beautiful creations form <i style=\"color: #FFFFFF;\">\"an endless fountain of immortal drink, / pouring unto us from the heaven's brink\"</i>—a celestial gift from the divine to nourish the mortal soul.</p>\n    </div>\n  </div>\n\n  <!-- Master Poetic Devices Table -->\n  <div style=\"background: rgba(30, 41, 59, 0.85); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 12px; padding: 20px; margin-bottom: 24px;\">\n    <h3 style=\"color: #00E676; margin: 0 0 16px 0; font-size: 18px; font-weight: 700;\">3. Master Literary & Poetic Devices Table</h3>\n    <div style=\"overflow-x: auto;\">\n      <table style=\"width: 100%; border-collapse: collapse; font-size: 14px; text-align: left;\">\n        <thead>\n          <tr style=\"background: rgba(0, 230, 118, 0.15); border-bottom: 2px solid #00E676;\">\n            <th style=\"padding: 10px 12px; color: #00E676;\">Poetic Device</th>\n            <th style=\"padding: 10px 12px; color: #FFFFFF;\">Example from Poem</th>\n            <th style=\"padding: 10px 12px; color: #CBD5E1;\">Poetic Significance & Explanation</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #00E676;\">Metaphor</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"bower quiet\"<br/>\"flowery band\"<br/>\"endless fountain of immortal drink\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">A bower compares beauty to a sheltered shady grove; flowery band compares our love for nature to a binding wreath; fountain of immortal drink compares eternal beauty to celestial nectar (ambrosia).</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06); background: rgba(15, 23, 42, 0.4);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #00E676;\">Transferred Epithet</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"gloomy days\"<br/>\"unhealthy and o'er-darkened ways\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">The human sorrow and moral depravity are grammatically transferred to the 'days' and 'ways', vividly depicting the psychological darkness of mortal life.</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #00E676;\">Oxymoron / Paradox</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"grandeur of the dooms\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">Juxtaposes 'grandeur' (glory, majesty) with 'dooms' (death, downfall, destruction), highlighting the sublime, tragic beauty found in the noble sacrifice of heroic martyrs.</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06); background: rgba(15, 23, 42, 0.4);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #00E676;\">Sensory Imagery</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"clear rills... cooling covert\"<br/>\"sprinkling of fair musk-rose blooms\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">Visual, tactile, and olfactory imagery evoking refreshing coolness, crystal waters, and sweet forest fragrances that counteract midsummer heat and emotional exhaustion.</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #00E676;\">Alliteration</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"noble natures\"<br/>\"simple sheep\"<br/>\"cooling covert\"<br/>\"band to bind\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">Repetition of consonant sounds ('n', 's', 'c', 'b') adds lyrical grace, soft melodious flow, and aesthetic pleasure to the verses.</td>\n          </tr>\n          <tr>\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #00E676;\">Inversion (Anastrophe)</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"are we wreathing a flowery band\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">Reversal of conventional syntactic word order emphasizes the daily human ritual of seeking beauty to endure worldly suffering.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n\n  <!-- Vocabulary Glossary -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 4px solid #00E676; border-radius: 0 12px 12px 0; padding: 18px 20px;\">\n    <h3 style=\"color: #00E676; margin: 0 0 12px 0; font-size: 17px; font-weight: 700;\">4. Essential Stanza Vocabulary</h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; font-size: 13px;\">\n      <div><b style=\"color: #00E676;\">Bower:</b> A pleasant, leafy, shady retreat under branches.</div>\n      <div><b style=\"color: #00E676;\">Morrow:</b> The following day / every successive dawn.</div>\n      <div><b style=\"color: #00E676;\">Despondence:</b> Dejection, loss of hope, emotional gloom.</div>\n      <div><b style=\"color: #00E676;\">Dearth:</b> Scarcity, acute lack or shortage (of noble minds).</div>\n      <div><b style=\"color: #00E676;\">Pall:</b> A dark shroud or covering over a coffin/gloom.</div>\n      <div><b style=\"color: #00E676;\">Boon:</b> A divine blessing or protective gift.</div>\n      <div><b style=\"color: #00E676;\">Rills:</b> Small crystal brooks or mountain streams.</div>\n      <div><b style=\"color: #00E676;\">Covert:</b> A concealed shelter of thick foliage or reeds.</div>\n      <div><b style=\"color: #00E676;\">Brake:</b> A dense growth of shrubs, ferns, and bushes.</div>\n      <div><b style=\"color: #00E676;\">Brink:</b> The edge, border, or celestial verge of heaven.</div>\n    </div>\n  </div>\n</div>\n";

export const c12EngF11HtmlSolutions = "\n<div style=\"padding: 16px; color: #F8FAFC; text-align: justify; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.85; font-size: 15px;\">\n\n  <!-- SECTION A: EXTRACT-BASED QUESTIONS -->\n  <div style=\"margin-bottom: 30px;\">\n    <div style=\"background: linear-gradient(135deg, rgba(0, 230, 118, 0.25), rgba(15, 23, 42, 0.95)); border: 1.5px solid #00E676; border-radius: 12px; padding: 14px 18px; margin-bottom: 20px;\">\n      <h2 style=\"color: #FFFFFF; font-size: 20px; font-weight: 800; margin: 0 0 4px 0;\">SECTION A: Extract-Based Questions (16 Marks)</h2>\n      <p style=\"color: #00E676; font-size: 13px; font-weight: 600; margin: 0;\">Board Pattern: 4 Objective Extracts • 4 Questions Each • Continuous Q1 to Q16</p>\n    </div>\n\n    <!-- Extract 1 -->\n    <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 18px; margin-bottom: 16px;\">\n      <p style=\"font-style: italic; color: #E2E8F0; margin: 0 0 8px 0; font-size: 14px;\">\n        \"A thing of beauty is a joy for ever:<br/>\n        Its loveliness increases; it will never<br/>\n        Pass into nothingness; but still will keep<br/>\n        A bower quiet for us, and a sleep<br/>\n        Full of sweet dreams, and health, and quiet breathing.\"\n      </p>\n      <span style=\"color: #00E676; font-size: 12px; font-weight: 700;\">— Extract 1 (Stanza 1)</span>\n    </div>\n\n    <!-- Q1 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q1: How does John Keats define the longevity and impact of a thing of beauty?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Keats defines beauty as an immortal source of perpetual joy. Unlike ephemeral physical goods that lose luster, the aesthetic charm of beauty multiplies over time in the observer's mind and never deteriorates into nothingness.</p>\n    </div>\n\n    <!-- Q2 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q2: What is meant by \"a bower quiet for us\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> A 'bower' is a peaceful, shady retreat formed by intertwining branches and dense foliage. Metaphorically, beauty constructs a soothing sanctuary of mental serenity that shields human beings from the scorching anxieties, tumult, and noise of the world.</p>\n    </div>\n\n    <!-- Q3 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q3: What four psychological and physical blessings does beauty bestow upon us?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Beauty blesses humanity with: (1) restful sleep, (2) sweet, calming dreams, (3) physical vitality and somatic health, and (4) tranquil, unhurried, peaceful breathing.</p>\n    </div>\n\n    <!-- Q4 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q4: What is the rhyme scheme and meter of these lines?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> The rhyme scheme follows heroic rhyming couplets (AABB), composed in fluent, enjambed iambic pentameter, lending the verses musical harmony and eternal flow.</p>\n    </div>\n\n    <!-- Extract 2 -->\n    <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 18px; margin-bottom: 16px;\">\n      <p style=\"font-style: italic; color: #E2E8F0; margin: 0 0 8px 0; font-size: 14px;\">\n        \"Therefore, on every morrow, are we wreathing<br/>\n        A flowery band to bind us to the earth,<br/>\n        Spite of despondence, of the inhuman dearth<br/>\n        Of noble natures, of the gloomy days,<br/>\n        Of all the unhealthy and o'er-darkened ways<br/>\n        Made for our searching: yes, in spite of all,<br/>\n        Some shape of beauty moves away the pall<br/>\n        From our dark spirits.\"\n      </p>\n      <span style=\"color: #00E676; font-size: 12px; font-weight: 700;\">— Extract 2 (Stanza 2)</span>\n    </div>\n\n    <!-- Q5 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q5: Why do we wreathe a \"flowery band\" every morning?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Wreathing a flowery band symbolizes establishing a joyful, loving connection with the natural world each dawn. This daily bond prevents humans from succumbing to existential despair and anchors our souls affectionately to earthly existence.</p>\n    </div>\n\n    <!-- Q6 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q6: What causes \"despondence\" and sorrow in human life according to Keats?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Human suffering arises from the acute scarcity (\"inhuman dearth\") of noble, righteous human beings, pervasive melancholic days, and the corrupt, deceitful, and crooked paths (\"unhealthy and o'er-darkened ways\") that humans tread in pursuit of selfish gain.</p>\n    </div>\n\n    <!-- Q7 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q7: Identify and explain the transferred epithet in this extract.</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> <b style=\"color: #00E676;\">\"Gloomy days\"</b> and <b style=\"color: #00E676;\">\"unhealthy and o'er-darkened ways\"</b> are transferred epithets. The days and paths themselves lack emotions; rather, human sorrow and immoral conduct are grammatically transferred to characterize the time and journeys.</p>\n    </div>\n\n    <!-- Q8 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q8: What does the \"pall\" symbolize, and how is it removed?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> A 'pall' is a dark, heavy shroud cast over a coffin or corpse, symbolizing the stifling cover of melancholy, depression, and hopelessness. It is lifted and cast away when our spirit encounters \"some shape of beauty\" in art or nature.</p>\n    </div>\n\n    <!-- Extract 3 -->\n    <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 18px; margin-bottom: 16px;\">\n      <p style=\"font-style: italic; color: #E2E8F0; margin: 0 0 8px 0; font-size: 14px;\">\n        \"Such the sun, the moon,<br/>\n        Trees old, and young, sprouting a shady boon<br/>\n        For simple sheep; and such are daffodils<br/>\n        With the green world they live in; and clear rills<br/>\n        That for themselves a cooling covert make<br/>\n        'Gainst the hot season; the mid forest brake,<br/>\n        Rich with a sprinkling of fair musk-rose blooms;\"\n      </p>\n      <span style=\"color: #00E676; font-size: 12px; font-weight: 700;\">— Extract 3 (Stanza 3)</span>\n    </div>\n\n    <!-- Q9 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q9: What natural elements are catalogued by the poet as shapes of beauty?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Keats catalogues: (1) the radiant sun, (2) the serene moon, (3) ancient and sapling trees offering leafy shade, (4) vibrant golden daffodils flourishing in lush greenery, (5) clear murmuring rills, and (6) woodland ferns sprinkled with sweet-smelling musk-roses.</p>\n    </div>\n\n    <!-- Q10 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q10: What is the \"shady boon\", and for whom is it sprouted?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> The \"shady boon\" is the protective canopy of leafy foliage sprouted by old and young trees. It provides a divine, sheltered blessing for \"simple sheep\", which also symbolically represents innocent, vulnerable human souls seeking respite.</p>\n    </div>\n\n    <!-- Q11 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q11: How do the \"clear rills\" protect themselves and nature against the summer heat?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> The crystal clear brooks create a \"cooling covert\"—a shady, protected alcove of overgrown grasses, aquatic ferns, and reeds along their embankments—preventing excessive evaporation and offering refreshing chill during the sweltering hot season.</p>\n    </div>\n\n    <!-- Q12 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q12: Point out instances of alliteration in this extract.</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Instances of alliteration include: <b style=\"color: #00E676;\">\"simple sheep\"</b> (repetition of 's' sound) and <b style=\"color: #00E676;\">\"cooling covert\"</b> (repetition of hard 'c' sound), which generate lyrical rhythm and auditory pleasure.</p>\n    </div>\n\n    <!-- Extract 4 -->\n    <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 18px; margin-bottom: 16px;\">\n      <p style=\"font-style: italic; color: #E2E8F0; margin: 0 0 8px 0; font-size: 14px;\">\n        \"And such too is the grandeur of the dooms<br/>\n        We have imagined for the mighty dead;<br/>\n        All lovely tales that we have heard or read:<br/>\n        An endless fountain of immortal drink,<br/>\n        Pouring unto us from the heaven's brink.\"\n      </p>\n      <span style=\"color: #00E676; font-size: 12px; font-weight: 700;\">— Extract 4 (Stanza 4)</span>\n    </div>\n\n    <!-- Q13 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q13: Who are the \"mighty dead\", and why is \"grandeur\" associated with their dooms?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> The \"mighty dead\" are legendary warriors, philosophers, martyrs, and noble ancestors who sacrificed their lives for noble causes. Their \"dooms\" (deaths) possess \"grandeur\" because they met death with heroic dignity, inspiring posterity through timeless tales of martyrdom.</p>\n    </div>\n\n    <!-- Q14 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q14: Explain the literary significance of \"All lovely tales that we have heard or read\".</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Keats expands beauty beyond physical nature to include the verbal and literary realm—folktales, epic poems, classical romances, and heroic histories that stimulate aesthetic imagination and uplift our spirits with timeless moral truths.</p>\n    </div>\n\n    <!-- Q15 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q15: What is the \"immortal drink\" and from where does it pour?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> The \"immortal drink\" is a metaphor for celestial nectar or ambrosia, symbolizing the eternal joy, spiritual sustenance, and divine truth radiating from all beautiful things. It pours perpetually from the edge of heaven (\"heaven's brink\") as a direct gift from God.</p>\n    </div>\n\n    <!-- Q16 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q16: Identify the poetic device in \"grandeur of the dooms\" and \"immortal drink\".</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> <b style=\"color: #00E676;\">\"Grandeur of the dooms\"</b> is an <b style=\"color: #00E676;\">Oxymoron</b> combining magnificence with death; <b style=\"color: #00E676;\">\"immortal drink\"</b> is a <b style=\"color: #00E676;\">Metaphor</b> comparing beauty's uplifting joy to the deathless nectar of the gods.</p>\n    </div>\n  </div>\n\n  <!-- SECTION B: SHORT ANSWER QUESTIONS -->\n  <div style=\"margin-bottom: 30px;\">\n    <div style=\"background: linear-gradient(135deg, rgba(0, 230, 118, 0.25), rgba(15, 23, 42, 0.95)); border: 1.5px solid #00E676; border-radius: 12px; padding: 14px 18px; margin-bottom: 20px;\">\n      <h2 style=\"color: #FFFFFF; font-size: 20px; font-weight: 800; margin: 0 0 4px 0;\">SECTION B: Short Answer Questions (3 Marks • 40–50 Words)</h2>\n      <p style=\"color: #00E676; font-size: 13px; font-weight: 600; margin: 0;\">Board Standard: Conceptual & Aesthetic Reasoning • 12 Questions (Q17 to Q28)</p>\n    </div>\n\n    <!-- Q17 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q17: Why does John Keats associate grandeur with the mighty dead?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> The mighty dead were heroic souls whose lives were defined by selfless valor and grand sacrifice. Their martyrdom is immortalized in glorious legends and poetry, casting an aura of majestic awe and sublime aesthetic inspiration across future generations.</p>\n    </div>\n\n    <!-- Q18 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q18: What image does Keats use to describe the beautiful bounty of the earth?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Keats uses the transcendent image of \"an endless fountain of immortal drink\" pouring straight from heaven's brink. This fountain ceaselessly showers divine aesthetic nourishment onto mortal souls, enriching their earthly existence.</p>\n    </div>\n\n    <!-- Q19 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q19: What makes human beings love life despite all suffering and despondence?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Despite sickness, sorrow, bereavement, and the dearth of noble friends, the presence of beautiful objects in nature and art lifts the dark pall from human spirits, filling our hearts with renewed joy and a deep desire to live.</p>\n    </div>\n\n    <!-- Q20 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q20: How do daffodils and clear rills provide solace to human senses?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Daffodils bring cheerful radiance within the green forest world, while murmuring crystal rills weave cooling leafy sanctuaries against summer heat, providing soothing visual freshness and acoustic therapy to weary souls.</p>\n    </div>\n\n    <!-- Q21 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q21: What does Keats mean by the \"inhuman dearth of noble natures\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Keats laments the painful rarity of genuinely virtuous, noble, and generous human beings in society. The majority of people succumb to petty selfishness, malice, and materialism, intensifying existential grief in sensitive minds.</p>\n    </div>\n\n    <!-- Q22 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q22: Why does Keats mention \"simple sheep\" in connection with old and young trees?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Trees provide unconditional, protective shade to simple sheep without discrimination. Symbolically, sheep represent innocent, vulnerable mortals, showing nature's benevolent grace in shielding all creatures from harsh worldly realities.</p>\n    </div>\n\n    <!-- Q23 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q23: How does the memory of a beautiful thing grow over time?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> The impression of beauty never fades into nothingness. Instead, its loveliness increases in human memory and imagination, transforming into an enduring spiritual sanctuary where the soul seeks refuge repeatedly throughout life.</p>\n    </div>\n\n    <!-- Q24 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q24: What are the \"unhealthy and o'er-darkened ways\" referred to in the poem?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> They refer to dishonest, corrupt, and deceitful paths pursued by individuals driven by greed, ego, and ambition. These misguided pursuits bring moral degradation, anxiety, and spiritual darkness to human existence.</p>\n    </div>\n\n    <!-- Q25 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q25: In what sense is beauty an antidote to mortality?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> While mortal human life is fragile, fleeting, and bounded by death, the experience and essence of beauty are immortal. Beauty links mortal beings to divine eternity, defying decay and spiritual demise.</p>\n    </div>\n\n    <!-- Q26 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q26: What role does the \"mid forest brake\" play in creating beauty?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> The mid-forest brake represents lush wild vegetation, dense ferns, and shrubs. Enriched by blooming musk-roses, it infuses the deep woods with sweet, intoxicating fragrance and enchanting visual beauty.</p>\n    </div>\n\n    <!-- Q27 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q27: How does Keats link classical mythology with aesthetic appreciation?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Keats draws from the Greek myth of Endymion's love for the Moon Goddess, illustrating how classical legends and poetic romance preserve the highest manifestations of sublime beauty and spiritual devotion across centuries.</p>\n    </div>\n\n    <!-- Q28 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E676; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q28: Why does the poet believe that beauty \"never passes into nothingness\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Physical forms may perish, but the emotional impression and spiritual joy generated by beauty remain eternal. They are absorbed into the soul, continuously inspiring and uplifting the human heart across lifetimes.</p>\n    </div>\n  </div>\n\n  <!-- SECTION C: LONG ANSWER QUESTIONS -->\n  <div style=\"margin-bottom: 30px;\">\n    <div style=\"background: linear-gradient(135deg, rgba(0, 230, 118, 0.25), rgba(15, 23, 42, 0.95)); border: 1.5px solid #00E676; border-radius: 12px; padding: 14px 18px; margin-bottom: 20px;\">\n      <h2 style=\"color: #FFFFFF; font-size: 20px; font-weight: 800; margin: 0 0 4px 0;\">SECTION C: Long Analytical Questions (6 Marks • 120–150 Words)</h2>\n      <p style=\"color: #00E676; font-size: 13px; font-weight: 600; margin: 0;\">3-Tier Model: Context & Romantic Philosophy • Thematic Dimensions • Board Synthesis • Q29 to Q34</p>\n    </div>\n\n    <!-- Q29 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #00E676; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q29: How does John Keats establish beauty as an everlasting source of joy and a powerful antidote to human melancholy?</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">1. Philosophical Premise & Longevity:</b> In the celebrated opening lines of <i>Endymion</i>, John Keats propounds the core Romantic doctrine: <i>\"A thing of beauty is a joy for ever.\"</i> True beauty is exempt from physical decay; its loveliness compounds in human consciousness rather than dissipating into oblivion. It creates a tranquil \"bower\"—a cool, green sanctuary that offers peaceful sleep, radiant health, and quiet breathing amid life's relentless stress.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">2. The Existential Struggle & The Flowery Band:</b> Keats confronts the harsh realities of mortal existence—pervasive despondence, the acute shortage of noble minds (\"inhuman dearth of noble natures\"), gloomy seasons, and the corrupt paths men tread. In the face of this bleak reality, humanity weaves a daily metaphorical \"flowery band\" to re-anchor itself to the living earth. When existential despair casts a heavy \"pall\" over human spirits, radiant manifestations of beauty—from sun and daffodils to murmuring streams—intervene to dispel the darkness.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #00E676;\">3. Critical Conclusion:</b> Ultimately, Keats elevates beauty from mere sensory pleasure into a transcendent spiritual therapy that redeems human existence from sorrow and connects mortal man to the eternal divine.</p>\n    </div>\n\n    <!-- Q30 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #00E676; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q30: Analyze the sensory imagery and natural catalogue deployed by Keats in \"A Thing of Beauty\".</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">1. Cosmic & Pastoral Harmony:</b> Keats orchestrates a vibrant sensory panorama that enchants visual, tactile, and olfactory senses. He begins with cosmic luminaries—the golden warmth of the sun and the serene glow of the moon—before descending to pastoral nature. Trees, both venerable and young, extend a \"shady boon\" of foliage to shield innocent sheep, establishing a sheltering landscape of benevolence.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">2. Tactile Refreshment & Fragrance:</b> Keats's sensory mastery shines in his depiction of golden daffodils illuminating the \"green world\" and \"clear rills\" of crystal mountain brooks. These streams sculpt a \"cooling covert\" of reeds and water foliage, providing tactile relief against midsummer heat. The olfactory dimension is enriched by the \"mid forest brake\", where wild ferns are sprinkled with blooming, fragrant musk-roses, evoking a rich woodland perfume.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #00E676;\">3. Critical Conclusion:</b> This catalogue proves that nature's beauty is holistic and restorative. By stimulating all human senses, Keats revitalizes weary spirits and demonstrates that the earth is filled with divine blessings for those who pause to observe.</p>\n    </div>\n\n    <!-- Q31 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #00E676; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q31: Discuss the synthesis of natural beauty, heroic history, and literature in Keats's concept of the \"immortal drink\".</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">1. Expanding the Realm of Beauty:</b> Keats does not restrict beauty to pastoral landscapes; he seamlessly synthesizes nature with human heroic heritage and the arts. He finds supreme beauty in the \"grandeur of the dooms we have imagined for the mighty dead\"—the noble, tragic sacrifices of historical martyrs and visionary heroes who defended noble ideals with their lives.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">2. Literature & The Immortal Fountain:</b> Alongside heroic acts, Keats celebrates \"all lovely tales that we have heard or read\"—classical mythologies, epics, and romances that preserve human wisdom. These diverse expressions of beauty culminate in the cosmic metaphor of an \"endless fountain of immortal drink\" (divine ambrosia/nectar) pouring endlessly from heaven's brink.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #00E676;\">3. Critical Conclusion:</b> Keats demonstrates that whether created by nature, enacted through heroic sacrifice, or immortalized in art, all beauty springs from a singular celestial source, conferring immortality upon mortal human consciousness.</p>\n    </div>\n\n    <!-- Q32 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #00E676; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q32: Explain the paradoxical phrase \"grandeur of the dooms\" and evaluate its aesthetic significance in the poem.</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">1. The Linguistic & Conceptual Paradox:</b> The expression \"grandeur of the dooms\" brings together two seemingly opposing ideas: 'grandeur' (glory, majesty, nobility) and 'dooms' (death, downfall, destruction). Keats applies this phrase to the \"mighty dead\"—valiant ancestors and martyrs who sacrificed their lives for honor, truth, or the defense of their homeland.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">2. The Sublime in Tragedy:</b> In Romantic aesthetics, death is not merely bleak biological extinction; when borne with fortitude and moral conviction, it achieves the status of the 'sublime'. The heroic deaths of ancient legends evoke pity, awe, and admiration, transforming tragedy into a supreme work of art that elevates the human spirit.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #00E676;\">3. Critical Conclusion:</b> Through this paradox, Keats broadens the definition of beauty beyond peaceful pleasantness to encompass solemn, magnificent sacrifices that permanently dignify the human condition.</p>\n    </div>\n\n    <!-- Q33 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #00E676; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q33: How does John Keats reflect the core characteristics of Romantic Poetry in \"A Thing of Beauty\"?</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">1. Worship of Nature & Sensuousness:</b> Keats's poem epitomizes quintessential Romanticism. Foremost is the passionate veneration of Nature as a living, benevolent sanctuary. Keats's trademark sensuousness—appealing directly to all five senses through imagery of cooling rills, shady bowers, and blooming musk-roses—embodies the Romantic pursuit of visceral emotional resonance.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">2. Medievalism, Myth, & Escapism:</b> The poem incorporates medieval chivalric longing and Greek myth (the legend of Endymion). Rather than dry Enlightenment rationalism, Keats embraces imaginative wonder, celebrating folklore and heroic legends (\"lovely tales that we have heard or read\") as bridges to transcendental truth.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #00E676;\">3. Melancholy & Idealism:</b> Keats acknowledges deep personal and collective suffering (\"gloomy days\", \"spite of despondence\"), yet counters it with radiant aesthetic idealism. This interplay of existential sorrow and transcendent beauty lies at the very heart of the Romantic worldview.</p>\n    </div>\n\n    <!-- Q34 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 22px;\">\n      <h3 style=\"color: #00E676; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q34: Evaluate the structural progression of \"A Thing of Beauty\" from personal physical refuge to celestial immortality.</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">1. Personal & Bodily Comfort:</b> The poem begins at an intimate, personal level. Beauty is presented as an immediate, somatic solace—providing a shady bower, sweet dreams, and quiet breathing to soothe the tired body and weary nervous system of the individual observer.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E676;\">2. Terrestrial & Communal Solace:</b> The poem widens outward to address collective societal despair—the lack of noble souls and dark, corrupt paths. It counters this despondence with an expansive inventory of terrestrial wonders: sun, moon, sheltering trees, bright daffodils, and mountain rills that sustain ecosystems and uplift humanity.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #00E676;\">3. Ascendance to the Celestial:</b> Finally, the poem ascends into the sublime realm of historical heroism and literary art. Keats culminates his journey with a cosmic vision: beauty is an \"endless fountain of immortal drink\" cascading from heaven's brink. The poem thus moves triumphantly from earthly bower to divine immortality.</p>\n    </div>\n  </div>\n\n  <!-- SECTION D: NCERT TEXTBOOK EXERCISES -->\n  <div style=\"margin-bottom: 20px;\">\n    <div style=\"background: linear-gradient(135deg, rgba(0, 230, 118, 0.25), rgba(15, 23, 42, 0.95)); border: 1.5px solid #00E676; border-radius: 12px; padding: 14px 18px; margin-bottom: 20px;\">\n      <h2 style=\"color: #FFFFFF; font-size: 20px; font-weight: 800; margin: 0 0 4px 0;\">SECTION D: NCERT Textbook Exercises (Thinking About The Poem)</h2>\n      <p style=\"color: #00E676; font-size: 13px; font-weight: 600; margin: 0;\">Official Curriculum Solutions • Questions Q35 to Q38</p>\n    </div>\n\n    <!-- Q35 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q35: List the things of beauty mentioned in the poem.</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> The things of beauty catalogued by Keats include: (1) the sun, (2) the moon, (3) old and young trees that sprout a shady blessing for simple sheep, (4) vibrant daffodils in their lush green environment, (5) clear rills that carve cooling leafy shelters against summer heat, (6) the mid-forest brake sprinkled with blooming wild musk-roses, (7) the heroic grandeur of the mighty dead, and (8) all lovely tales and legends that we have heard or read.</p>\n    </div>\n\n    <!-- Q36 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q36: List the things that cause suffering and pain.</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> The things causing suffering and pain are: (1) deep despondence and despair, (2) the acute scarcity (\"inhuman dearth\") of noble and virtuous people, (3) gloomy, melancholic days filled with sorrow, and (4) the unhealthy and crooked paths (\"o'er-darkened ways\") that human beings navigate in selfish, corrupt pursuit of material ends.</p>\n    </div>\n\n    <!-- Q37 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q37: What does the line, 'Therefore, on every morrow, are we wreathing a flowery band to bind us to the earth' suggest to you?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> It suggests that each morning, despite suffering, disillusionment, and pain, human beings actively seek out and cultivate connections with the beauty of nature. This daily bond acts like a fragrant, woven garland connecting our souls affectionately to earthly life, preventing us from surrendering to despair.</p>\n    </div>\n\n    <!-- Q38 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 230, 118, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E676; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q38: What makes human beings love life in spite of troubles and sufferings?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E676; font-weight: bold;\">✓ Answer:</span> Human beings love life because \"some shape of beauty moves away the pall from our dark spirits.\" The eternal joy radiated by natural wonders, great art, and inspiring legends lifts the burden of sorrow from our hearts, giving us comfort, hope, and the spiritual strength to cherish existence.</p>\n    </div>\n  </div>\n\n</div>\n";

